import 'package:material_ui/material_ui.dart';

/// Strings for Ongaku-only screens. Kept out of upstream's ARB files, which
/// are regenerated by Musify's translation platform and would conflict.
/// Falls back to English for languages not listed here.
class OngakuStrings {
  const OngakuStrings._(this._values);

  final Map<String, String> _values;

  static OngakuStrings of(BuildContext context) =>
      forLanguage(Localizations.maybeLocaleOf(context)?.languageCode ?? 'en');

  /// For places without a [BuildContext], such as the Android Auto browser.
  static OngakuStrings forLanguage(String code) =>
      OngakuStrings._(_all[code] ?? _all['en']!);

  String _t(String key) => _values[key] ?? _all['en']![key]!;

  String get localFiles => _t('localFiles');
  String get addFiles => _t('addFiles');
  String get addFolder => _t('addFolder');
  String get rescan => _t('rescan');
  String get emptyTitle => _t('emptyTitle');
  String get emptyBody => _t('emptyBody');
  String get folders => _t('folders');
  String get removeFolder => _t('removeFolder');
  String get permissionDenied => _t('permissionDenied');
  String get noNewSongs => _t('noNewSongs');
  String get sortTitle => _t('sortTitle');
  String get sortArtist => _t('sortArtist');
  String get sortRecent => _t('sortRecent');
  String get autoRecent => _t('autoRecent');
  String get autoLibrary => _t('autoLibrary');
  String get autoPlaylists => _t('autoPlaylists');
  String get autoQueue => _t('autoQueue');
  String get autoLiked => _t('autoLiked');
  String get autoDownloaded => _t('autoDownloaded');
  String songsAdded(int n) => _t('songsAdded').replaceAll('{n}', '$n');
  String songCount(int n) =>
      _t(n == 1 ? 'songCountOne' : 'songCountMany').replaceAll('{n}', '$n');

  static const _all = <String, Map<String, String>>{
    'en': {
      'localFiles': 'Local Files',
      'addFiles': 'Add Files',
      'addFolder': 'Add Folder',
      'rescan': 'Refresh',
      'emptyTitle': 'No Local Music',
      'emptyBody':
          'Add audio files or a whole folder from this device. '
          'MP3, M4A, FLAC, OGG, Opus and WAV are supported.',
      'folders': 'Folders',
      'removeFolder': 'Remove folder',
      'permissionDenied': 'Allow access to music and audio in the system settings to add a folder.',
      'noNewSongs': 'No new songs found',
      'songsAdded': '{n} songs added',
      'songCountOne': '{n} song',
      'songCountMany': '{n} songs',
      'sortTitle': 'Title',
      'sortArtist': 'Artist',
      'sortRecent': 'Recently Added',
      'autoRecent': 'Recents',
      'autoLibrary': 'Library',
      'autoPlaylists': 'Playlists',
      'autoQueue': 'Up Next',
      'autoLiked': 'Liked Songs',
      'autoDownloaded': 'Downloaded',
    },
    'fr': {
      'localFiles': 'Fichiers locaux',
      'addFiles': 'Ajouter des fichiers',
      'addFolder': 'Ajouter un dossier',
      'rescan': 'Actualiser',
      'emptyTitle': 'Aucune musique locale',
      'emptyBody':
          "Ajoutez des fichiers audio ou un dossier entier depuis l'appareil. "
          'Formats pris en charge : MP3, M4A, FLAC, OGG, Opus et WAV.',
      'folders': 'Dossiers',
      'removeFolder': 'Retirer le dossier',
      'permissionDenied':
          "Autorisez l'accès à la musique et à l'audio dans les réglages "
          'du système pour ajouter un dossier.',
      'noNewSongs': 'Aucun nouveau morceau trouvé',
      'songsAdded': '{n} morceaux ajoutés',
      'songCountOne': '{n} morceau',
      'songCountMany': '{n} morceaux',
      'sortTitle': 'Titre',
      'sortArtist': 'Artiste',
      'sortRecent': 'Ajouts récents',
      'autoRecent': 'Récents',
      'autoLibrary': 'Bibliothèque',
      'autoPlaylists': 'Playlists',
      'autoQueue': 'À suivre',
      'autoLiked': 'Titres aimés',
      'autoDownloaded': 'Téléchargés',
    },
  };
}
